import { detectCollision } from './labels-collision.utils.js';
import type { ChartLegendOrientation } from '../../../../types/legend.js';

export const getCollisionDetails = (
  mainIdx: number,
  symmetricIdx: number,
  elements: DOMRect[],
  numberOfItems: number,
  orientation: ChartLegendOrientation,
  symmetricVariant: boolean,
) => {
  const mainElement = elements[mainIdx];
  const symmetricElement = elements[symmetricIdx];
  let symmetricCollisionRight = false;
  let symmetricCollisionLeft = false;
  let symmetricCollisionWithAnchor = false;

  const {
    collisionRight: mainCollisionRight,
    collisionLeft: mainCollisionLeft,
    collisionWithAnchor: mainCollisionWithAnchor,
  } = detectCollision(
    mainElement,
    mainIdx,
    elements,
    numberOfItems,
    orientation,
  );

  if (symmetricVariant) {
    const { collisionRight, collisionLeft, collisionWithAnchor } =
      detectCollision(
        symmetricElement,
        symmetricIdx,
        elements,
        numberOfItems,
        orientation,
      );
    symmetricCollisionRight = collisionRight;
    symmetricCollisionLeft = collisionLeft;
    symmetricCollisionWithAnchor = collisionWithAnchor;
  }

  const hasMainCollision =
    mainCollisionRight || mainCollisionLeft || mainCollisionWithAnchor;

  const hasSymmetricCollision =
    symmetricCollisionRight ||
    symmetricCollisionLeft ||
    symmetricCollisionWithAnchor;

  const hasCollision = hasMainCollision || hasSymmetricCollision;
  const hasAnchorCollision =
    mainCollisionWithAnchor || symmetricCollisionWithAnchor;

  return {
    hasCollision,
    hasAnchorCollision,
  };
};
